#include "../rsbench-cuda/simulation.cu"
#include <vector>
#include <fstream>
#include <algorithm>
#include <string>
#include <cmath>
const double SENT=-777.;
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<double>load(const char*n){std::ifstream in(std::string(RS_ROOT)+"/"+n,std::ios::binary|std::ios::ate);if(!in)exit(3);size_t bytes=in.tellg();if(bytes%8)exit(4);std::vector<double>v(bytes/8);in.seekg(0);if(!in.read((char*)v.data(),bytes))exit(5);return v;}
void add(std::vector<double>&v,int x){v.push_back(x);}void add(std::vector<double>&v,double x){v.push_back(x);}void add(std::vector<double>&v,Pole x){v.insert(v.end(),{x.MP_EA.r,x.MP_EA.i,x.MP_RT.r,x.MP_RT.i,x.MP_RA.r,x.MP_RA.i,x.MP_RF.r,x.MP_RF.i,(double)x.l_value});}void add(std::vector<double>&v,Window x){v.insert(v.end(),{x.T,x.A,x.F,(double)x.start,(double)x.end});}
template<class T>T sentinel();template<>int sentinel<int>(){return -777;}template<>double sentinel<double>(){return SENT;}template<>Pole sentinel<Pole>(){Pole p={};p.MP_EA=p.MP_RT=p.MP_RA=p.MP_RF={SENT,SENT};p.l_value=-777;return p;}template<>Window sentinel<Window>(){return{SENT,SENT,SENT,-777,-777};}
template<class T>std::vector<T>get(T*p,size_t n){std::vector<T>v(n);ck(cudaMemcpy(v.data(),p,n*sizeof(T),cudaMemcpyDefault));return v;}
template<class T>struct Guarded{T*base,*p;size_t n;Guarded(const std::vector<T>&v):n(v.size()){std::vector<T>h(n+2,sentinel<T>());std::copy(v.begin(),v.end(),h.begin()+1);ck(cudaMalloc(&base,h.size()*sizeof(T)));ck(cudaMemcpy(base,h.data(),h.size()*sizeof(T),cudaMemcpyDefault));p=base+1;}void capture(std::vector<double>&v){for(T x:get(p,n))add(v,x);}void guards(std::vector<double>&v){add(v,get(base,1)[0]);add(v,get(p+n,1)[0]);}};
__global__ void study_details(const int*num,const double*concs,const int*mats,const int*nwin,const double*pseudo,const Window*windows,const Pole*poles,double*details,int n,int doppler,int maxw,int maxp,int maxn){size_t i=threadIdx.x+blockIdx.x*blockDim.x;if(i<n){uint64_t seed=fast_forward_LCG(STARTING_SEED,2*i);double E=LCG_random_double(&seed);int mat=pick_mat(&seed);double xs[4]={0};calculate_macro_xs(xs,mat,E,doppler,4,num,mats,maxn,concs,nwin,pseudo,windows,poles,maxw,maxp);double*o=details+8*i;o[0]=E;o[1]=mat;o[2]=(uint32_t)seed;o[3]=seed>>32;for(int j=0;j<4;j++)o[4+j]=xs[j];}}
struct Case{int n,doppler;Guarded<int>*out;Guarded<double>*details;};
int main(){auto f=load("fixtures_f64.bin"),oracle=load("oracle_f64.bin");size_t pos=0;int nc=f[pos++],maxp=f[pos++],maxw=f[pos++],maxn=f[pos++],ncases=f[pos++];std::vector<double>header(f.begin(),f.begin()+5+ncases*2);pos=header.size();auto ints=[&](int n){std::vector<int>v(n);for(int&i:v)i=f.at(pos++);return v;};auto doubles=[&](int n){std::vector<double>v(f.begin()+pos,f.begin()+pos+n);pos+=n;return v;};Guarded<int>num(ints(12)),mats(ints(12*maxn)),nwin(ints(nc));Guarded<double>concs(doubles(12*maxn)),pseudo(doubles(nc*4));std::vector<Pole>ph(nc*maxp);for(auto&x:ph){x={};x.MP_EA={f.at(pos),f.at(pos+1)};x.MP_RT={f.at(pos+2),f.at(pos+3)};x.MP_RA={f.at(pos+4),f.at(pos+5)};x.MP_RF={f.at(pos+6),f.at(pos+7)};x.l_value=f.at(pos+8);pos+=9;}Guarded<Pole>poles(ph);std::vector<Window>wh(nc*maxw);for(auto&x:wh){x={f.at(pos),f.at(pos+1),f.at(pos+2),(int)f.at(pos+3),(int)f.at(pos+4)};pos+=5;}Guarded<Window>windows(wh);if(pos!=f.size())return 6;printf("LAYOUT Pole=%zu Window=%zu\n",sizeof(Pole),sizeof(Window));std::vector<Case>cases;for(int c=0;c<ncases;c++){int n=header[5+2*c],d=header[6+2*c];cases.push_back({n,d,new Guarded<int>(std::vector<int>(n,-777)),new Guarded<double>(std::vector<double>(8*n,SENT))});}
 auto readfixture=[&]{auto v=header;num.capture(v);mats.capture(v);nwin.capture(v);concs.capture(v);pseudo.capture(v);poles.capture(v);windows.capture(v);return v;};
 auto run=[&](Case&c,bool diagnostic){if(diagnostic)study_details<<<(c.n+255)/256,256>>>(num.p,concs.p,mats.p,nwin.p,pseudo.p,windows.p,poles.p,c.details->p,c.n,c.doppler,maxw,maxp,maxn);else lookup<<<(c.n+255)/256,256>>>(num.p,concs.p,mats.p,c.out->p,nwin.p,pseudo.p,windows.p,poles.p,c.n,c.doppler,4,maxw,maxp,maxn);ck(cudaGetLastError());ck(cudaDeviceSynchronize());};for(auto&c:cases){run(c,false);run(c,true);}for(int trial=1;trial<=5;trial++){auto payload=readfixture();bool ok=payload==f;double total=0,maxabs=0,maxbudget=0;size_t op=0;std::vector<double>times;for(auto&c:cases){std::vector<int>ov(c.n+2,-777);std::vector<double>dv(8*c.n+2,SENT);ck(cudaMemcpy(c.out->base,ov.data(),ov.size()*4,cudaMemcpyDefault));ck(cudaMemcpy(c.details->base,dv.data(),dv.size()*8,cudaMemcpyDefault));ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();run(c,false);double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();total+=elapsed;times.push_back(elapsed);auto observed=get(c.out->p,c.n);run(c,true);auto details=get(c.details->p,8*c.n);for(int i=0;i<c.n;i++){double row[9];row[0]=observed[i];for(int j=0;j<8;j++)row[j+1]=details[8*i+j];for(int j=0;j<9;j++){double ref=oracle.at(op++),err=fabs(row[j]-ref),budget=1e-9+1e-8*fabs(ref);ok &=std::isfinite(row[j])&&(j<5 ? row[j]==ref : err<=budget);if(j>=5){maxabs=std::max(maxabs,err);maxbudget=std::max(maxbudget,err/budget);}payload.push_back(row[j]);}}size_t gp=payload.size();c.out->guards(payload);c.details->guards(payload);for(size_t j=gp;j<payload.size();j++)ok &=payload[j]==SENT;}auto readonly=readfixture();ok &=readonly==f;payload.insert(payload.end(),readonly.begin(),readonly.end());size_t gp=payload.size();num.guards(payload);mats.guards(payload);nwin.guards(payload);concs.guards(payload);pseudo.guards(payload);poles.guards(payload);windows.guards(payload);for(size_t j=gp;j<payload.size();j++)ok &=payload[j]==SENT;std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);out.write((char*)payload.data(),payload.size()*8);out.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"max_normalized_oracle_budget\":%.17g,\"timing_region\":\"sum8_source_event_lookup_kernels_context_complete\",\"jit_excluded\":true,\"internal_repeats\":1,\"timed_kernel_calls\":8,\"untimed_diagnostic_kernel_calls\":8,\"case_times_seconds\":[",trial,total,ok?"true":"false",payload.size(),maxabs,maxbudget);for(size_t j=0;j<times.size();j++)printf("%s%.17g",j?",":"",times[j]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),payload.size());if(!ok)return 7;}return 0;}
